function transformDataWithoutCategory(data: number[]): SimplePlotDataType {
  let retData: SimplePlotDataType = [];
  if (data.length === 0) {
    return retData;
  }

  if (!hasSetXAxis) {
    let prevMinValue = Infinity;
    let prevMaxValue = -Infinity;
    if (isLinearAxisData(xyChartData.xAxis)) {
        prevMinValue = xyChartData.xAxis.min;
        prevMaxValue = xyChartData.xAxis.max;
    }
    setXAxisRangeData(Math.min(prevMinValue, 1), Math.max(prevMaxValue, data.length));
  }

  if (!hasSetYAxis) {
    setYAxisRangeFromPlotData(data);
  }

  if (isBandAxisData(xyChartData.xAxis)) {
    retData = xyChartData.xAxis.categories.map((c, i) => [c, data[i]]);
  }

  if (isLinearAxisData(xyChartData.xAxis)) {
    let min = xyChartData.xAxis.min;
    let max = xyChartData.xAxis.max;

    if (data.length === 1) {
      // For backwards compatibility, avoid divide-by-zero error
      retData = [[`${min}`, data[0]]];
    } else {
      const step = (max - min) / (data.length - 1);
      retData = data.map((datum, index) => [`${min + index * step}`, datum]);
    }
  }

  return retData;
}

