function viteServeRawFsMiddleware(req, res, next) {
    let url;
    try {
        url = new URL(req.url!, 'http://example.com');
    } catch (e) {
        // Assuming req.url! is always valid based on original code
        return next();
    }

    // In some cases (e.g. linked monorepos) files outside of root will
    // reference assets that are also out of served root. In such cases
    // the paths are rewritten to `/@fs/` prefixed paths and must be served by
    // searching based from fs root.
    if (url.pathname.startsWith(FS_PREFIX)) {
        let pathname = decodeURIComponent(url.pathname);

        // restrict files outside of `fs.allow`
        if (!ensureServingAccess(
            slash(path.resolve(fsPathFromId(pathname))), 
            server, 
            res, 
            next
        )) {
            return;
        }

        let newPathname = pathname.substring(FS_PREFIX.length);
        if (isWindows) {
            newPathname = newPathname.replace(/^[A-Z]:/i, '');
        }

        url.pathname = encodeURIComponent(newPathname);
        req.url = url.href.substring(url.origin.length);
        serveFromRoot(req, res, next);
    } else {
        next();
    }
}

