handleUpgrade(request, connection, headData, callback) {
    connection.on('error', socketOnError);

    let websocketKey = 
      request.headers['sec-websocket-key'] !== undefined
        ? request.headers['sec-websocket-key'].trim()
        : false;
    let wsVersion = +request.headers['sec-websocket-version'];
    let extraHeaders = {};

    if (
      request.method !== 'GET' ||
      request.headers.upgrade.toLowerCase() !== 'websocket' ||
      !websocketKey ||
      !keyRegex.test(websocketKey) ||
      (wsVersion !== 8 && wsVersion !== 13) ||
      !this.shouldHandle(request)
    ) {
      return abortHandshake(connection, 400);
    }

    if (this.options.perMessageDeflate) {
      const deflateInstance = new PerMessageDeflate(
        this.options.perMessageDeflate,
        true,
        this.options.maxPayload
      );

      try {
        const parsedOffers = parse(request.headers['sec-websocket-extensions']);

        if (parsedOffers[PerMessageDeflate.extensionName]) {
          deflateInstance.accept(parsedOffers[PerMessageDeflate.extensionName]);
          extraHeaders[PerMessageDeflate.extensionName] = deflateInstance;
        }
      } catch (err) {
        return abortHandshake(connection, 400);
      }
    }

    //
    // Optionally call external client verification handler.
    //
    if (this.options.verifyClient) {
      const clientInfo = {
        origin: 
          request.headers[`${wsVersion === 8 ? 'sec-websocket-origin' : 'origin'}`],
        secure: !!(request.socket.authorized || request.socket.encrypted),
        request: request
      };

      if (this.options.verifyClient.length === 2) {
        this.options.verifyClient(clientInfo, (verified, code, message, headers) => {
          if (!verified) {
