/**
 * Helper function to format a date according to the specified locale.
 * @param {moment.Moment} momentObj - The moment object to format.
 * @param {string} locale - The locale code (e.g., 'hi', 'ar').
 * @param {string} formatStr - The format string (e.g., 'YYYY-MM-DD').
 * @returns {string} The formatted date string.
 */
function formatLocalizedDate(momentObj, locale, formatStr) {
    if (!momentObj || !locale || !formatStr) {
        return "Invalid input.";
    }

    // Temporarily set the locale for accurate formatting
    const originalLocale = moment.locale();
    moment.locale(locale);

    const formatted = momentObj.format(formatStr);

    // Restore the original locale
    moment.locale(originalLocale);

    return formatted;
}

/**
 * Converts a date object to a localized string format based on the provided locale.
 * @param {Date} dateInput - The date object.
 * @param {string} locale - The locale code.
 * @returns {string} The localized date string.
 */
function getLocalizedDateString(dateInput, locale) {
    const momentObj = moment(dateInput);
    // Use a generic, recognizable format for demonstration, but ideally, this should be passed.
    return formatLocalizedDate(momentObj, locale, 'LLLL');
}

/**
 * Displays the current date and time formatted for a specified locale.
 * @param {string} locale - The locale code.
 */
function displayCurrentDateTime(locale) {
    const now = new Date();
    console.log(`
============================================`);
    console.log(`Formatted Current Date & Time for Locale: ${locale.toUpperCase()}`);
    console.log(`============================================`);

    try {
        // Demonstrating a few popular formats
        console.log(`Full Date (LLLL): ${formatLocalizedDate(moment(now), locale, 'LLLL')}`);
        console.log(`Short Date (L):   ${formatLocalizedDate(moment(now), locale, 'L')}`);
        console.log(`Full Date & Time (LLLLL): ${formatLocalizedDate(moment(now), locale, 'LLLLL')}`);
        console.log(`Current Time (LT): ${formatLocalizedDate(moment(now), locale, 'LT')}`);
    } catch (e) {
        console.error(`Could not format date for locale ${locale}:`, e.message);
    }
}

/**
 * Calculates and displays the date relative to the current time in the specified locale.
 * @param {string} locale - The locale code.
 */
function displayRelativeDate(locale) {
    console.log(`
============================================`);
    console.log(`Relative Time Indicators for Locale: ${locale.toUpperCase()}`);
    console.log(`============================================`);

    const now = new Date();

    // Note: These are illustrative as 'moment-with-locales-loader' doesn't expose a simple 'relative' function.
    // We rely on 'calendar' directives defined in the locales.
    console.log(`[Today]: ${formatLocalizedDate(moment(now), locale, 'L')}`);
    console.log(`[Yesterday]: ${formatLocalizedDate(moment(now).subtract(1, 'day'), locale, 'L')}`);
    console.log(`[Tomorrow]: ${formatLocalizedDate(moment(now).add(1, 'day'), locale, 'L')}`);

    // Relative time (e.g., 'in 3 hours') is highly locale-dependent and hard to simulate without knowing the exact implementation used by the library.
    console.log(`
(Relative Time indicators depend on locale implementation; checking simple markers:)`);
    console.log(`Next Week Indicator: ${formatLocalizedDate(moment(now).add(7, 'days'), locale, 'LLLL')}`);
}


// ===============================================================
// DEMONSTRATIONS
// ===============================================================

// 1. Telugu (Example of non-Latin script)
displayCurrentDateTime('te');
displayRelativeDate('te');

// 2. Thai (Example of different date format/meridiem)
displayCurrentDateTime('th');
displayRelativeDate('th');

// 3. Tagalog (Example of MM/D/YYYY format)
displayCurrentDateTime('tl-ph');
displayRelativeDate('tl-ph');

// 4. Turkish (Example of suffix calculation)
displayCurrentDateTime('tr');
displayRelativeDate('tr');

// 5. Hindi (Indian locale - assuming 'hi' is available or using a default Hindi pattern)
// NOTE: Since 'hi' is not in the provided set, this will likely fail gracefully or use 'en'.
// For demonstration, we will use a locale that is definitely present.

// 6. English (Default Check)
displayCurrentDateTime('en');
displayRelativeDate('en');

// 7. Uzbek (Uzbek-Latin)
displayCurrentDateTime('uz-latn');
displayRelativeDate('uz-latn');

// 8. Vietnamese (Shows 'sa'/'ch' meridiem change)
displayCurrentDateTime('vi');
displayRelativeDate('vi');

// 9. Chinese (Taiwan) - Shows different structure for year/month/day
displayCurrentDateTime('zh-tw');
displayRelativeDate('zh-tw');

// 10. Japanese style (Pseudo) - General comparison
displayCurrentDateTime('x-pseudo');
displayRelativeDate('x-pseudo');

// Cleanup/Final check
console.log(`
============================================`);
console.log(`Demonstration complete. Time is now: ${moment().format('LLLLL')}`);
