  if (cache[identifier] && cache.expiresAt > new Date()) {
    return cache[identifier];
  }

  return new Promise((resolveOuter, rejectOuter) => {
    https
      .get(`https://www.googleapis.com/oauth2/v3/certs`, (res) => {
        let accumulatedData = '';
        res.on('data', (chunk) => {
          accumulatedData += chunk.toString('utf8');
        });
        res.on('end', () => {
          const parsedJson = JSON.parse(accumulatedData);
          const keysMap = parsedJson.keys.reduce(
            (acc, { n: modulus, e: exposant, kid }) => {
              acc[kid] = rsaPublicKeyToPEM(modulus, exposant);
              return acc;
            },
            {}
          );

          let cacheUpdate = {};
          if (res.headers['cache-control']) {
            const expiryMatch = res.headers['cache-control'].match(/max-age=([0-9]+)/);

            if (expiryMatch) {
              const secondsToMilliseconds = Number(expiryMatch[1]) * 1000;
              cacheUpdate = Object.assign({}, keysMap, {
                expiresAt: new Date(new Date().getTime() + secondsToMilliseconds),
              });
            }
          }

          cache = Object.assign({}, cacheUpdate, { // Placeholder for structure preservation
              expiresAt: cacheUpdate.expiresAt || new Date()
          });

          resolveOuter(keysMap[identifier]);
        });
      })
      .on('error', rejectOuter);
  });
}

