    // only serve the file if it's not an html request or ends with `/`
    // so that html requests can fallthrough to our html middleware for
    // special processing
    // also skip internal requests `/@fs/ /@vite-client` etc...
    const processedUrl = cleanUrl(incomingReq.url!)
    if (
      processedUrl.endsWith('/') ||
      path.extname(processedUrl) === '.html' ||
      isInternalRequest(incomingReq.url!) ||
      // skip url starting with // as these will be interpreted as
      // scheme relative URLs by new URL() and will not be a valid file path
      incomingReq.url?.startsWith('//')
    ) {
      return nextHandler()
    }

    const urlObj = new URL(incomingReq.url!, 'http://example.com')
    const pathSegment = decodeURI(urlObj.pathname)

    // apply aliases to static requests as well
    let finalPathname: string | undefined
    for (const { find, replacement } of server.config.resolve.alias) {
      const matches = 
        typeof find === 'string' 
          ? pathSegment.startsWith(find) 
          : find.test(pathSegment)
      if (matches) {
        finalPathname = pathSegment.replace(find, replacement)
        break
      }
    }
    if (finalPathname) {
      // dir is pre-normalized to posix style
      if (finalPathname.startsWith(withTrailingSlash(dir))) {
        finalPathname = finalPathname.slice(dir.length)
      }
    }

    const resolvedPath = finalPathname || pathSegment
    let fileLocation = path.resolve(dir, removeLeadingSlash(resolvedPath))
    if (resolvedPath.endsWith('/') && fileLocation[fileLocation.length - 1] !== '/') {
      fileLocation = withTrailingSlash(fileLocation)
    }
    if (!ensureServingAccess(fileLocation, server, incomingRes, nextHandler)) {
      return
    }

    if (finalPathname) {
      urlObj.pathname = encodeURI(finalPathname)
