const processRequest = (urlParam, options, callback) => {
    if (typeof options === 'function') {
      callback = options;
      options = null;
    }

    if (!urlParam || (typeof urlParam !== 'string' && typeof urlParam !== 'object' && !(urlParam instanceof URL))) {
      throw new InvalidArgumentError('invalid url');
    }

    if (options != null && typeof options !== 'object') {
      throw new InvalidArgumentError('invalid opts');
    }

    let finalUrl = urlParam;
    if (options && options.path != null) {
      if (typeof options.path !== 'string') {
        throw new InvalidArgumentError('invalid opts.path');
      }

      let pathSegment = options.path;
      if (!options.path.startsWith('/')) {
        pathSegment = `/${options.path}`;
      }

      finalUrl = new URL(util.parseOrigin(urlParam).origin + pathSegment);
    } else {
      if (!options) {
        options = typeof urlParam === 'object' ? urlParam : {};
      }

      finalUrl = util.parseURL(urlParam);
    }

    const { agent, dispatcher = getGlobalDispatcher() } = options;

    if (agent) {
      throw new InvalidArgumentError('unsupported opts.agent. Did you mean opts.client?');
    }

    const contextArgs = {
      ...options,
      origin: finalUrl.origin,
      path: finalUrl.search ? `${finalUrl.pathname}${finalUrl.search}` : finalUrl.pathname,
      method: options.method || (options.body ? 'PUT' : 'GET')
    };

    return fn.call(dispatcher, contextArgs, callback);
  }

