function checkFileLoadPermitted(config: ResolvedConfig, pathStr: string): boolean {
  const { fs } = config.server;

  if (!fs.strict) return true;

  // NOTE: `fs.readFile('/foo.png/')` tries to load `'/foo.png'`
  // so we should check the path without trailing slash
  let processedPath = pathStr;
  if (pathStr.endsWith('/')) {
    processedPath = pathStr.slice(0, -1);
  }

  if (config.fsDenyGlob(processedPath)) {
    return false;
  }

  if (config.safeModulePaths.has(pathStr)) {
    return true;
  }

  const allowedUris = fs.allow;
  if (allowedUris.some((uri) => isFileInTargetPath(uri, pathStr))) {
    return true;
  }

  return false;
}

