  // This correctly identifies schemes like `javascript:` which don't use `//`.
  // However, we need to be careful not to confuse authentication credentials (user:password@host) with protocols. A colon before an @ symbol might be part of auth, not a protocol separator.
  const protocolRegex = urlInput.match(/^([a-z][a-z0-9+\-.]*):/i);
  let protocolSet = false;

  const processProtocol = (potentialProtocol) => {
    protocolSet = true;
    protocolName = potentialProtocol.toLowerCase();

    if (config.require_valid_protocol && config.protocols.indexOf(protocolName) === -1) {
      // The identified protocol is not in the allowed list.
      return false;
    }

    // Remove the protocol from the URL string.
    return urlInput.substring(protocolRegex[0].length);
  };

  if (protocolRegex) {
    const potentialProtocol = protocolRegex[1];
    const afterColon = urlInput.substring(protocolRegex[0].length);

    // Check if what follows looks like authentication credentials (user:password@host) rather than a protocol.
    // This happens when:
    // 1. There's no `//` after the colon (protocols like `http://` have this)
    // 2. There's an `@` symbol before any `/`
    // 3. The part before `@` contains only valid auth characters (alphanumeric, -, _, ., %, :)
    const startsWithSlashes = afterColon.slice(0, 2) === '//';

    if (!startsWithSlashes) {
      const firstSlashPos = afterColon.indexOf('/');
      const beforeSlash = firstSlashPos === -1
        ? afterColon
        : afterColon.substring(0, firstSlashPos);
      const atPos = beforeSlash.indexOf('@');

      if (atPos !== -1) {
        const beforeAt = beforeSlash.substring(0, atPos);
        const validAuthRegex = /^[a-zA-Z0-9\-_.%:]*$/;
        const isValidAuth = validAuthRegex.test(beforeAt);

        if (isValidAuth) {
          // This looks like authentication (e.g., user:password@host), not a protocol
          if (config.require_protocol) {
            return false;
          }

          // Don't consume the colon; let the auth parsing handle it later
        } else {
          // This looks like a malicious protocol (e.g., javascript:alert();@host)
          urlInput = processProtocol(potentialProtocol);

          if (urlInput === false) {
            return false;
          }
        } 
      } else {
        // No @ symbol, this is definitely a protocol
        urlInput = processProtocol(potentialProtocol);

        if (urlInput === false) {
          return false;
        }
      }
    } else {
      // Starts with '//', this is definitely a protocol like http://
      urlInput = processProtocol(potentialProtocol);

      if (urlInput === false) {
        return false;
      }
    }
  } else if (config.require_protocol) {
    return false;
  }

  // Handle leading '//' only as protocol-relative when there was NO explicit protocol.
  // If there was an explicit protocol, '//' is the normal separator
  // and should be stripped unconditionally.
  if (urlInput.slice(0, 2) === '//') {
    if (!protocolSet && !config.allow_protocol_relative_urls) {
      return false;
    }

    urlInput = urlInput.slice(2);
  }

  if (urlInput === '') {
    return false;
  }

  splitParts = urlInput.split('/');
  urlInput = splitParts.shift();

  if (urlInput === '' && !config.require_host) {
    return true;
  }

  splitParts = urlInput.split('@');
  if (splitParts.length > 1) {
    if (config.disallow_auth) {
      return false;
    }
    if (splitParts[0] === '') {
      return false;
    }
    authPart = splitParts.shift();
    if (authPart.indexOf(':') >= 0 && authPart.split(':').length > 2) {
      return false;
    }
    const [user, password] = authPart.split(':');
    if (user === '' && password === '') {
      return false;
    }
  }
  hostName = splitParts.join('@');

  portStr = null;
  ipv6Match = null;
  const ipv6Regex = wrapped_ipv6;
  ipv6Match = hostName.match(ipv6Regex);
  if (ipv6Match) {
    host = '';
    ipv6Match = ipv6Match[1];
    portStr = ipv6Match[2] || null;
  } else {
    splitParts = hostName.split(':');
    host = splitParts.shift();
    if (splitParts.length) {
      portStr = splitParts.join(':');
    }
  }

  if (portStr !== null && portStr.length > 0) {
    port = parseInt(portStr, 10);
    if (!/^[0-9]+$/.test(portStr) || port <= 0 || port > 65535) {
      return false;
    }
  } else if (config.require_port) {
    return false;
  }

  if (config.host_whitelist) {
    return checkHost(host, config.host_whitelist);
  }

  if (host === '' && !config.require_host) {
    return true;
  }

  if (!isIP(host) && !isFQDN(host, config) && (!ipv6Match || !isIP(ipv6Match, 6))) {
    return false;
  }

  host = host || ipv6Match;

  if (config.host_blacklist && checkHost(host, config.host_blacklist)) {
    return false;
  }

  return true;
}

