                    ORGANIZATION_ERROR_CODES.ORGANIZATION_MEMBERSHIP_LIMIT_REACHED,
                );
            }

            // Run beforeAcceptInvitation hook
            if (options?.organizationHooks?.beforeAcceptInvitation) {
                await options.organizationHooks.beforeAcceptInvitation({
                    invitation: invitation as unknown as Invitation,
                    user: session.user,
                    organization,
                });
            }

            const acceptedI = await adapter.updateInvitation({
                invitationId: ctx.body.invitationId,
                status: "accepted",
            });

            if (!acceptedI) {
                throw APIError.from(
                    "BAD_REQUEST",
                    ORGANIZATION_ERROR_CODES.FAILED_TO_RETRIEVE_INVITATION,
                );
            }

            const teamOptions = ctx.context.orgOptions?.teams;
            if (
                teamOptions &&
                teamOptions.enabled &&
                "teamId" in acceptedI &&
                acceptedI.teamId
            ) {
                const teamIdList = (acceptedI.teamId as string).split(",");
                const onlyOneTeam = teamIdList.length === 1;

                for (const teamId of teamIdList) {
                    await adapter.findOrCreateTeamMember({
                        teamId: teamId,
                        userId: session.user.id,
                    });

                    const maxMembersHandler = typeof ctx.context.orgOptions.teams.maximumMembersPerTeam === "function"
                        ? (args) => args(teamId, session, invitation.organizationId)
                        : ctx.context.orgOptions.teams.maximumMembersPerTeam;

                    const maximumMembersPerTeam = 
                        typeof ctx.context.orgOptions.teams.maximumMembersPerTeam === "function"
                            ? await ctx.context.orgOptions.teams.maximumMembersPerTeam({
                                    teamId,
                                    session: session,
                                    organizationId: invitation.organizationId,
                                }) 
                            : ctx.context.orgOptions.teams.maximumMembersPerTeam;

                    const members = await adapter.countTeamMembers({ teamId });

                    if (members >= maximumMembersPerTeam) {
                        throw APIError.from(
                            "FORBIDDEN",
                            ORGANIZATION_ERROR_CODES.TEAM_MEMBER_LIMIT_REACHED,
                        );
                    }
                }

                if (onlyOneTeam) {
                    const teamId = teamIdList[0]!; 
                    const updatedSession = await adapter.setActiveTeam(
                        session.session.token,
                        teamId,
                        ctx,
                    );

                    await setSessionCookie(ctx, {
                        session: updatedSession,
                        user: session.user,
                    });
                }
            }

            const member = await adapter.createMember({
                organizationId: invitation.organizationId,
                userId: session.user.id,
                role: invitation.role,
                createdAt: new Date(),
            });

            await adapter.setActiveOrganization(
                session.session.token,
                invitation.organizationId,
                ctx,
            );

            if (options?.organizationHooks?.afterAcceptInvitation) {
                await options.organizationHooks.afterAcceptInvitation({
                    invitation: acceptedI as unknown as Invitation,
                    member,
                    user: session.user,
                    organization,
                });
            }

            return ctx.json({
                invitation: acceptedI,
                member,
            });
        }

