static validateParams(
    request: IncomingMessage,
    queryData: UrlWithParsedQuery['query'],
    config: NextConfigComplete,
    developmentMode: boolean
  ): ImageParamsResult | { errorMessage: string } {
    const imageConfig = config.images
    const { 
      deviceSizes = [],
      imageSizes = [],
      domains = [],
      minimumCacheTTL = 60,
      formats = ['image/webp'],
    } = imageConfig
    const remotePatternsConfig = config.images?.remotePatterns || []
    const { url: sourceUrl, w: widthParam, q: qualityParam } = queryData
    let finalHref: string

    if (domains.length > 0) {
      Log.warnOnce(
        'The "images.domains" configuration is deprecated. Please use "images.remotePatterns" configuration instead.'
      )
    }

    if (!sourceUrl) {
      return { errorMessage: '"url" parameter is required' }
    }
    if (Array.isArray(sourceUrl)) {
      return { errorMessage: '"url" parameter cannot be an array' }
    }

    if (sourceUrl.length > 3072) {
      return { errorMessage: '"url" parameter is too long' }
    }

    if (sourceUrl.startsWith('//')) {
      return {
        errorMessage: '"url" parameter cannot be a protocol-relative URL (//)',
      }
    }

    if (sourceUrl.startsWith('/_next/image')) {
      return {
        errorMessage: '"url" parameter cannot be recursive',
      }
    }

    let isAbsoluteFlag: boolean

    if (sourceUrl.startsWith('/')) {
      finalHref = sourceUrl
      isAbsoluteFlag = false
    } else {
      let parsedUrl: URL

      try {
        parsedUrl = new URL(sourceUrl)
        finalHref = parsedUrl.toString()
        isAbsoluteFlag = true
      } catch (_error) {
        return { errorMessage: '"url" parameter is invalid' }
      }

      if (!['http:', 'https:'].includes(parsedUrl.protocol)) {
        return { errorMessage: '"url" parameter is invalid' }
      }

      if (!hasMatch(domains, remotePatternsConfig, parsedUrl)) {
        return { errorMessage: '"url" parameter is not allowed' }
      }
    }

    if (!widthParam) {
      return { errorMessage: '"w" parameter (width) is required' }
    }
    if (Array.isArray(widthParam)) {
      return { errorMessage: '"w" parameter (width) cannot be an array' }
    }

    if (!qualityParam) {
      return { errorMessage: '"q" parameter (quality) is required' }
    }
    if (Array.isArray(qualityParam)) {
      return { errorMessage: '"q" parameter (quality) cannot be an array' }
    }

    const calculatedWidth = parseInt(widthParam, 10)

    if (isNaN(calculatedWidth) || calculatedWidth <= 0) {
      return {
        errorMessage: '"w" parameter (width) must be a number greater than 0',
      }
    }

    const combinedSizes = [...(deviceSizes || []), ...(imageSizes || [])]

    if (developmentMode) {
      combinedSizes.push(BLUR_IMG_SIZE)
    }

    const sizeIsValid = 
      combinedSizes.includes(calculatedWidth) || (developmentMode && calculatedWidth <= BLUR_IMG_SIZE)

    if (!sizeIsValid) {
      return {
        errorMessage: `"w" parameter (width) of ${calculatedWidth} is not allowed`,
      }
    }

    const calculatedQuality = parseInt(qualityParam)

    if (isNaN(calculatedQuality) || calculatedQuality < 1 || calculatedQuality > 100) {
      return {
        errorMessage:
          '"q" parameter (quality) must be a number between 1 and 100',
      }
    }

    const mimeTypeResult = getSupportedMimeType(formats || [], request.headers['accept'])

    const isMediaStatic = sourceUrl.startsWith(
      `${config.basePath || ''}/_next/static/media`
    )

    return {
      href: finalHref,
      sizes: combinedSizes,
      isAbsolute: isAbsoluteFlag,
      isStatic: isMediaStatic,
      width: calculatedWidth,
      quality: calculatedQuality,
      mimeType: mimeTypeResult,
      minimumCacheTTL: minimumCacheTTL,
    }
  }

